WITH cleaned AS (SELECT *, DATEDIFF(CURRENT_DATE(), event_time) / 30 AS months_since_event_time, CASE WHEN page IN ('/search', '/home') THEN 'Tier 1' ELSE 'Other' END AS page_group, COALESCE(page, 'UNKNOWN') AS page_filled FROM web_events WHERE event_time >= DATE '2023-03-10' AND page IS NOT NULL) SELECT id, session_id, event_time, months_since_event_time, page_filled, SUM(duration_sec) OVER w_part AS running_sum_duration_sec, AVG(duration_sec) OVER w_part AS running_avg_duration_sec, MAX(duration_sec) OVER w_part AS running_max_duration_sec FROM cleaned WHERE months_since_event_time >= 35 WINDOW w_part AS (PARTITION BY page ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
